# Hypothesis: Keep only cells that are part of a line of 3+ same-value cells
output_grid = np.zeros((19, 19), dtype=int)

def find_connected_component(grid_np, start_r, start_c):
    """BFS to find connected component of same-value cells"""
    val = grid_np[start_r, start_c]
    if val == 0:
        return []

    visited = set()
    component = []
    queue = [(start_r, start_c)]
    visited.add((start_r, start_c))

    while queue:
        r, c = queue.pop(0)
        component.append((r,c))

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 19 and 0 <= nc < 19:
                if grid_np[nr,nc] == val and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    queue.append((nr,nc))
    return component

# Find all components of size >= 3
for r in range(19):
    for c in range(19):
        if grid_np[r,c] != 0:
            comp = find_connected_component(grid_np, r, c)
            if len(comp) >= 3:
                # Mark all cells in this component
                for cr, cc in comp:
                    output_grid[cr, cc] = grid_np[cr, cc]

result = [[int(x) for x in row] for row in output_grid]
print("Components with size >= 3:")
