# Hypothesis: Keep cells that have any horizontal OR vertical run of 2+ same-value neighbors
from collections import deque

grid_np = np.array(grid)
output_grid = np.zeros((19, 19), dtype=int)

for r in range(19):
    for c in range(19):
        val = grid_np[r,c]
        if val == 0:
            continue

        # Check horizontal runs starting at this position
        has_horizontal_run = False
        for length in [2, 3]:
            if c + length <= 19:
                run_ok = True
                for dc in range(1, length):
                    if grid_np[r, c+dc] != val:
                        run_ok = False
                        break
                if run_ok:
                    has_horizontal_run = True
                    break

        # Check vertical runs starting at this position
        has_vertical_run = False
        for length in [2, 3]:
            if r + length <= 19:
                run_ok = True
                for dr in range(1, length):
                    if grid_np[r+dr, c] != val:
                        run_ok = False
                        break
                if run_ok:
                    has_vertical_run = True
                    break

        if has_horizontal_run or has_vertical_run:
            output_grid[r,c] = val

result = [[int(x) for x in row] for row in output_grid]
